package com.example.assets_management.security.scope; import com.example.assets_management.security.context.CurrentUserService; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import java.util.*; @Service("departmentScopeService") @RequiredArgsConstructor public class DepartmentScopeService { private final CurrentUserService current; public boolean sameDepartment(UUID departmentId){return departmentId!=null&&Objects.equals(departmentId,current.getDepartmentId());} public boolean canAccessDepartment(UUID departmentId){return sameDepartment(departmentId)||current.getBranchId()==null;} }
